contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint amount) public {
        require(to != address(0));
        uint senderBefore = c.balanceOf(address(this));
        uint receiverBefore = c.balanceOf(to);
        bool ok;
        if (amount <= senderBefore) {
            ok = c.transfer(to, amount);
            assert(ok && c.balanceOf(address(this)) == senderBefore - amount && c.balanceOf(to) == receiverBefore + amount);
        } else {
            try c.transfer(to, amount) returns (bool r) { ok = r; }
            catch { ok = false; }
            assert(!ok && c.balanceOf(address(this)) == senderBefore && c.balanceOf(to) == receiverBefore);
        }
    }
    receive() external payable {}
}

