    function run(uint amount, address recipient) public {
        require(recipient != address(0));
        c.getTokens();
        uint balBefore = c.balanceOf(address(this));
        uint recipBefore = c.balanceOf(recipient);
        uint supplyBefore = c.totalSupply();
        bool reverted;
        if (amount <= balBefore) {
            bool ok = c.transfer(recipient, amount);
            reverted = !ok;
        } else {
            try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }
        }
        assert(
            reverted == (amount > balBefore) &&
            (reverted || (
                c.balanceOf(recipient) == recipBefore + amount &&
                c.balanceOf(address(this)) == balBefore - amount &&
                c.totalSupply() == supplyBefore
            ))
        );
    }
    receive() external payable {}
}

