contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint amount) public {
        require(to != address(0));
        require(amount > 0);
        // Owner (this contract) claims the distributed balance so it can transfer.
        c.NETM();
        uint myBal = c.balanceOf(address(this));
        require(amount <= myBal);
        // Approve this contract as spender of exactly `amount`.
        c.approve(address(this), amount);
        require(c.allowance(address(this), address(this)) == amount);
        // Spend the allowance via transferFrom.
        c.transferFrom(address(this), to, amount);
        assert(c.balanceOf(to) == amount
            && c.balanceOf(address(this)) + amount == myBal
            && c.allowance(address(this), address(this)) == 0);
    }
    receive() external payable {}
}

